import{_ as e,c as o,o as l,a4 as c}from"./chunks/framework.BYxathSa.js";const u=JSON.parse('{"title":"Q8：Flex 布局常见属性及 flex: 1 的含义","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q8.md","filePath":"frontend/q8.md","lastUpdated":null}'),d={name:"frontend/q8.md"},t=c('<h1 id="q8-flex-布局常见属性及-flex-1-的含义" tabindex="-1">Q8：Flex 布局常见属性及 <code>flex: 1</code> 的含义 <a class="header-anchor" href="#q8-flex-布局常见属性及-flex-1-的含义" aria-label="Permalink to &quot;Q8：Flex 布局常见属性及 `flex: 1` 的含义&quot;">​</a></h1><p>Flex 布局是一维布局模型，容器和项目都有对应属性。</p><p><strong>容器属性（父元素）</strong>：</p><ul><li><code>flex-direction</code>：主轴方向（<code>row</code> | <code>column</code>）。</li><li><code>flex-wrap</code>：是否换行。</li><li><code>justify-content</code>：主轴对齐。</li><li><code>align-items</code>：交叉轴单行对齐。</li><li><code>align-content</code>：多根轴线的对齐方式。</li></ul><p><strong>项目属性（子元素）</strong>：</p><ul><li><code>flex-grow</code>：放大比例，默认 0，有剩余空间也不放大。</li><li><code>flex-shrink</code>：缩小比例，默认 1，空间不足时会缩小。</li><li><code>flex-basis</code>：项目初始主轴尺寸，默认 <code>auto</code>（元素本来的大小）。</li><li><code>flex</code>：简写属性，推荐使用。</li><li><code>align-self</code>：可覆盖父元素的 <code>align-items</code>。</li></ul><p><strong><code>flex: 1</code> 的秘密</strong><br><code>flex: 1</code> 是 <code>flex: 1 1 0%</code> 的简写。意为：</p><ul><li><code>flex-grow: 1</code>：有剩余空间就放大。</li><li><code>flex-shrink: 1</code>：空间不足就缩小。</li><li><code>flex-basis: 0%</code>：项目在分配空间前的基础尺寸为 0。<br> 这使得所有设置 <code>flex: 1</code> 的子元素会<strong>严格按照比例均分容器剩下的所有空间</strong>，而忽略内容自身宽度，非常适合等分布局。</li></ul>',8),i=[t];function n(a,r,s,f,x,_){return l(),o("div",null,i)}const g=e(d,[["render",n]]);export{u as __pageData,g as default};
